  const frames: ForecastTuple[] = input.map(f=>[
    f.baseTime??null, f.validTime??null, f.status??null, f.intensityClass??null,
    f.rgba ? [f.rgba.r,f.rgba.g,f.rgba.b,f.rgba.a] : null,
  ]);
