  else if (expectedFrames===null) reason="EXPECTED_COUNT_UNKNOWN";
  else if (frames.length!==expectedFrames) reason="FRAME_COUNT_MISMATCH";
  else if (usableFrames!==frames.length) reason="UNUSABLE_FRAME_STATUS";
